  &lt;span class="nt"&gt;--name&lt;/span&gt; &lt;span class="s2"&gt;"cron-health-check"&lt;/span&gt; &lt;span class="se"&gt;\&lt;/span&gt;
  &lt;span class="nt"&gt;--schedule&lt;/span&gt; &lt;span class="s2"&gt;"0 */6 * * *"&lt;/span&gt; &lt;span class="se"&gt;\ &lt;/span&gt; &lt;span class="c"&gt;# Every 6 hours&lt;/span&gt;
